begin;
select plan(6);
select ok(not has_function_privilege('authenticated','public.capture_books_export_snapshot(uuid)','execute'),'project owner archive capture stays private');
select ok(not has_function_privilege('anon','public.capture_books_legacy_ownership_evidence(uuid,uuid)','execute'),'legacy population capture stays private');
select ok(not (select prosecdef from pg_proc where oid='public.capture_books_export_snapshot(uuid)'::regprocedure),'archive capture preserves invoker authority');
select ok(position('books_project_entity_reviews' in (select string_agg(pg_get_functiondef(oid),' ') from pg_proc where pronamespace='public'::regnamespace and proname like 'capture\_books\_export\_snapshot%')) > 0,'snapshot capture includes authoritative project owners');
select ok(position('population_contract_version' in pg_get_functiondef('public.books_legacy_entity_review_guard()'::regprocedure)) > 0,'legacy review distinguishes retained and current population contracts');
select is((select column_default from information_schema.columns where table_schema='public' and table_name='books_legacy_entity_proposals' and column_name='population_contract_version'),'1','old immutable proposals retain contract one');
select * from finish();
rollback;
